'use strict';
const scene=new Scene(),g=scene.ctx,rockets=[],particles=[];let idle=0,automatic=false,phrase='ATOM';
function launch(x,y){if(rockets.length>=10)return;idle=0;rockets.push({x:x+(Math.random()-.5)*32,y:340,tx:x,ty:Math.max(76,Math.min(y,278)),hue:Math.random()*360});scene.tone(260,.15,.16);}
function burst(r){const count=scene.motion.matches?36:70,shape=Math.floor(Math.random()*3);for(let i=0;i<count&&particles.length<1600;i++){const a=i/count*Math.PI*2,s=shape===1?3.2:1+Math.random()*3.2;particles.push({x:r.x,y:r.y,vx:Math.cos(a)*s,vy:Math.sin(a)*s*(shape===2?.6:1),life:1,hue:r.hue+(Math.random()-.5)*40,decay:.008+Math.random()*.01});}scene.tone(140,.22,.25);}
function textBurst(){const c=document.createElement('canvas');c.width=480;c.height=360;const x=c.getContext('2d');x.font='bold '+(phrase.length>5?42:64)+'px sans-serif';x.textAlign='center';x.fillStyle='#fff';x.fillText(phrase,240,200,420);const data=x.getImageData(0,0,480,360).data;const step=scene.motion.matches?6:4;for(let y=70;y<280;y+=step)for(let px=24;px<456;px+=step)if(data[(y*480+px)*4+3]>128&&particles.length<1600)particles.push({x:240,y:200,tx:px,ty:y,life:1.6,hue:30+px/3,decay:.006,text:true});}
function finale(){for(let i=0;i<4;i++)scene.after(()=>launch(60+Math.random()*360,80+Math.random()*150),i*160);}
scene.listen(scene.canvas,'pointerdown',e=>{e.preventDefault();const [x,y]=scene.point(e);launch(x,y);});scene.key(e=>{if(/^[1-9]$/.test(e.key)){const i=+e.key-1;launch(80+(i%3)*160,85+Math.floor(i/3)*65);}else if(e.key==='Enter')finale();});
scene.listen(document.querySelector('#finale'),'click',finale);scene.listen(document.querySelector('#auto'),'click',e=>{automatic=!automatic;e.target.textContent=automatic?'停止连放':'自动连放';e.target.setAttribute('aria-pressed',String(automatic));});
const sheet=document.querySelector('.sheet');scene.listen(document.querySelector('#words'),'click',()=>{sheet.hidden=false;sheet.querySelector('input').value=phrase;sheet.querySelector('input').focus();});scene.listen(document.querySelector('#cancel'),'click',()=>sheet.hidden=true);scene.listen(document.querySelector('#send-words'),'click',()=>{phrase=sheet.querySelector('input').value.trim().slice(0,8)||'ATOM';sheet.hidden=true;textBurst();});
scene.loop(dt=>{idle+=dt;if(automatic&&idle>90)launch(60+Math.random()*360,80+Math.random()*150);g.fillStyle='rgba(2,4,12,.22)';g.fillRect(0,0,480,360);g.globalCompositeOperation='lighter';for(let i=rockets.length-1;i>=0;i--){const r=rockets[i];r.x+=(r.tx-r.x)*(1-Math.pow(.94,dt));r.y+=(r.ty-r.y)*(1-Math.pow(.94,dt));g.fillStyle=`hsl(${r.hue},100%,75%)`;g.fillRect(r.x-1,r.y-1,3,6);if(Math.abs(r.y-r.ty)<4){burst(r);rockets.splice(i,1);}}
 for(let i=particles.length-1;i>=0;i--){const p=particles[i];if(p.text){p.x+=(p.tx-p.x)*(1-Math.pow(.92,dt));p.y+=(p.ty-p.y)*(1-Math.pow(.92,dt));if(p.life<.8)p.ty+=.4*dt;}else{p.vx*=Math.pow(.985,dt);p.vy=p.vy*Math.pow(.985,dt)+.035*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;}p.life-=p.decay*dt;if(p.life<=0){particles.splice(i,1);continue;}g.fillStyle=`hsla(${p.hue},100%,${55+Math.min(1,p.life)*20}%,${Math.min(1,p.life)})`;g.fillRect(p.x,p.y,2.4,2.4);}g.globalCompositeOperation='source-over';});
